static bool Naive(Node? n)
{
    if (n is null) return true;
    if (n.Left is not null && n.Left.Val >= n.Val) return false;
    if (n.Right is not null && n.Right.Val <= n.Val) return false;
    return Naive(n.Left) && Naive(n.Right);
}

